import random

def rotl8(v,n):
    return ((v<<n)|(v>>(8-n)))&0xff

def g(a,b,x):
    return rotl8((a+b+x)&0xff,2)

def f(x):
    xs=[(x>>(8*i))&0xff for i in range(4)]
    y=[0]*4
    y[2]=g(xs[3]^xs[2], xs[1]^xs[0], 1)
    y[3]=g(xs[3], y[2], 0)
    y[1]=g(xs[1]^xs[0], y[2], 0)
    y[0]=g(xs[0], y[1], 1)
    return sum(y[i]<<(8*i) for i in range(4))

def dot(mask,x):
    return bin((mask&x)).count('1')&1

random.seed(999)
pts=[random.getrandbits(32) for _ in range(10000)]
rels=[
    (0x00040000,0x01010101,1),
    (0x04000400,0x01000101,0),
    (0x04040400,0x00010000,1),
]
for a,b,c in rels:
    ok=all(dot(a,f(x))==dot(b,x)^c for x in pts)
    print(f"out=0x{a:08x} in=0x{b:08x} c={c}: {'EXACT' if ok else 'FAIL'}")
